{"sql":"-- Create table monthly_reports
CREATE TABLE IF NOT EXISTS employees.monthly_reports (
  report_id SERIAL PRIMARY KEY,
  report_date DATE NOT NULL,
  department_count INTEGER NOT NULL,
  total_employees INTEGER NOT NULL,
  avg_salary DECIMAL NOT NULL,
  generated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Create generate_monthly_report stored procedure
CREATE OR REPLACE FUNCTION employees.generate_monthly_report(report_date DATE)
RETURNS INTEGER AS $$
DECLARE
  dep_count INTEGER;
  tot_emps INTEGER;
  avg_sal DECIMAL;
  rid INTEGER;
BEGIN
  SELECT COUNT(*) INTO dep_count FROM employees.department;
  SELECT COUNT(*) INTO tot_emps FROM employees.employee;
  SELECT AVG(amount) INTO avg_sal FROM employees.salary WHERE to_date = '9999-01-01';

  INSERT INTO employees.monthly_reports(report_date, department_count, total_employees, avg_salary)
  VALUES(report_date, dep_count, tot_emps, avg_sal)
  RETURNING report_id INTO rid;

  RETURN rid;
END;
$$ LANGUAGE plpgsql;"}

{"sql":"-- Create salary_alerts table for alert storage
CREATE TABLE IF NOT EXISTS employees.salary_alerts (
  alert_id SERIAL PRIMARY KEY,
  employee_id BIGINT NOT NULL,
  salary_amount BIGINT NOT NULL,
  alert_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  status VARCHAR(20) NOT NULL DEFAULT 'new'
);

-- Create function for high_salary_alert trigger
CREATE OR REPLACE FUNCTION employees.fn_high_salary_alert()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.amount > 120000 THEN
    INSERT INTO employees.salary_alerts(employee_id, salary_amount, alert_date, status)
    VALUES (NEW.employee_id, NEW.amount, NOW(), 'new');
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create trigger high_salary_alert on salary insert
DROP TRIGGER IF EXISTS high_salary_alert ON employees.salary;
CREATE TRIGGER high_salary_alert
AFTER INSERT ON employees.salary
FOR EACH ROW
EXECUTE FUNCTION employees.fn_high_salary_alert();"}

